def leftsearch(prefs, n, l, h, k, i):
	while l <= h:
		m = (l + h) // 2
		if prefs[i - 1] - prefs[m] > k:
			l = m + 1
		elif m > 0:
			if prefs[i - 1] - prefs[m - 1] > k:
				return m
			else:
				h = m - 1
		else:
			return m
	return -1

def rightsearch(prefs, n, l, h, k, i):
	while l <= h:
		m = (l + h) // 2
		if prefs[m] - prefs[i] > k:
			h = m - 1
		elif m < n - 1:
			if prefs[m + 1] - prefs[i] > k:
				return m + 1
			else:
				l = m + 1
		else:
			return m
	return -1

def func(n, arr):
	if n == 1:
		return [0]
	if n == 2:
		return [1, 1]
	prefs = [0] * n
	prefs[0] = arr[0]
	for i in range(1, n):
		prefs[i] = prefs[i - 1] + arr[i]
	l = [0] * n
	for i in range(n):
		if i == 0:
			m2 = rightsearch(prefs, n, i + 1, n - 1, arr[i], i)
			if m2 == -1:
				l[i + 1] += 1
				l[i] -= 1
			else:
				l[m2] += 1
				l[i] -= 1
		elif i == n - 1:
			m1 = leftsearch(prefs, n, 0, i - 1, arr[i], i)
			l[i - 1] += 1
			if m1 > 0:
				l[m1 - 1] -= 1
		else:
			m1 = leftsearch(prefs, n, 0, i - 1, arr[i], i)
			l[i - 1] += 1
			if m1 > 0:
				l[m1 - 1] -= 1
			m2 = rightsearch(prefs, n, i + 1, n - 1, arr[i], i)
			if m2 == -1:
				l[i + 1] += 1
				l[i] -= 1
			else:
				l[m2] += 1
				l[i] -= 1
	suffs = [0] * n
	suffs[n - 1] = l[n - 1]
	for i in range(n - 2, -1, -1):
		suffs[i] = suffs[i + 1] + l[i]
	return suffs
for _ in range(int(input())):
	n = int(input())
	arr = list(map(int, input().split()))
	l1 = func(n, arr)
